// spec: .qa/e2e/specs/profile.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

async function openLevel(page: Page) {
  await page.getByRole('button', { name: /^רמת התחזקות: / }).click();
  const slider = page.getByRole('dialog').getByRole('slider', { name: 'רמת ההתחזקות' });
  await slider.focus(); // не кликать по слайдеру — клик сдвигает значение
  return slider;
}

async function saveDialog(page: Page, alertText: string) {
  await page.getByRole('dialog').getByRole('button', { name: 'שמירה' }).click();
  await expect(page.getByRole('alert').filter({ hasText: alertText })).toBeVisible();
  await expect(page.getByRole('dialog')).toHaveCount(0);
}

test.describe('Профиль — вошедший пользователь', () => {
  test('PR-04 Правка предпочтений (רמת התחזקות, נוסח) — «השינוי נשמר», применяется на главной, переживает reload #6a86f7f9 @data @mobile', async ({ page }) => {
    try {
      await page.goto('/profile');
      await expect(page.getByRole('button', { name: 'נוסח תפילה: אשכנז. מעבר לשלב כדי לשנות' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'רמת התחזקות: כל יום. מעבר לשלב כדי לשנות' })).toBeVisible();

      // 1. «רמת התחזקות» → стрелка на один шаг («6 פעמים בשבוע») → «שמירה».
      const slider = await openLevel(page);
      await expect(slider).toHaveAttribute('aria-valuetext', 'כל יום');
      await page.keyboard.press('ArrowRight'); // RTL: вправо — меньше
      await expect(slider).toHaveAttribute('aria-valuetext', '6 פעמים בשבוע');
      await saveDialog(page, 'רמת התחזקות: השינוי נשמר.');

      // 2. «נוסח תפילה» → «נוסח עדות המזרח» (не меняет выбор) → «נוסח ספרד» → «שמירה».
      await page.getByRole('button', { name: /^נוסח תפילה: / }).click();
      const dialog = page.getByRole('dialog');
      const east = dialog.getByRole('radio', { name: /^נוסח עדות המזרח/ });
      await expect(east).toHaveAttribute('aria-disabled', 'true');
      await east.click({ force: true });
      await expect(east).toHaveAttribute('aria-checked', 'false');
      await expect(dialog.getByRole('radio', { name: /^נוסח אשכנז/ })).toHaveAttribute('aria-checked', 'true');
      await dialog.getByRole('radio', { name: /^נוסח ספרד/ }).click();
      await expect(dialog.getByRole('radio', { name: /^נוסח ספרד/ })).toHaveAttribute('aria-checked', 'true');
      await saveDialog(page, 'נוסח: השינוי נשמר.');

      // 3. Reload `/profile`; открыть `/home`.
      await page.reload();
      await expect(page.getByRole('button', { name: 'נוסח תפילה: ספרד. מעבר לשלב כדי לשנות' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'רמת התחזקות: 6 פעמים בשבוע. מעבר לשלב כדי לשנות' })).toBeVisible();
      await page.goto('/home');
      await expect(page.getByText('נוסח ספרד', { exact: true })).toBeVisible({ timeout: 20_000 });
    } finally {
      // 4. Уборка: «נוסח אשכנז» → «שמירה»; «כל יום» → «שמירה»; reload `/profile` и `/home`.
      await page.goto('/profile');
      // Сначала дождаться загрузки профиля, затем читать текущие значения.
      await expect(page.getByRole('button', { name: /^נוסח תפילה: / })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByRole('button', { name: /^רמת התחזקות: / })).toBeVisible();
      if (await page.getByRole('button', { name: /^נוסח תפילה: ספרד/ }).isVisible()) {
        await page.getByRole('button', { name: /^נוסח תפילה: / }).click();
        await page.getByRole('dialog').getByRole('radio', { name: /^נוסח אשכנז/ }).click();
        await saveDialog(page, 'נוסח: השינוי נשמר.');
      }
      if (!(await page.getByRole('button', { name: 'רמת התחזקות: כל יום. מעבר לשלב כדי לשנות' }).isVisible())) {
        const slider = await openLevel(page);
        for (let i = 0; i < 6; i++) {
          if ((await slider.getAttribute('aria-valuetext')) === 'כל יום') break;
          await page.keyboard.press('ArrowLeft'); // RTL: влево — больше
        }
        await expect(slider).toHaveAttribute('aria-valuetext', 'כל יום');
        await saveDialog(page, 'רמת התחזקות: השינוי נשמר.');
      }
      await page.reload();
      await expect(page.getByRole('button', { name: 'נוסח תפילה: אשכנז. מעבר לשלב כדי לשנות' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'רמת התחזקות: כל יום. מעבר לשלב כדי לשנות' })).toBeVisible();
      await page.goto('/home');
      await expect(page.getByText('נוסח אשכנז', { exact: true })).toBeVisible({ timeout: 20_000 });
    }
  });
});
